// A workspace package of this project's own, standing in for the shape cal.com
// uses: persistence goes through `@calcom/prisma`, which configures one client and
// re-exports it, and no application file imports `@prisma/client` by name at all.
//
// Nothing here declares a data layer. The client is configured and handed on, and
// the type of everything it hands on is still declared by the library, which is why
// the descriptor is found under the library's name without anybody writing the
// wrapper's name down anywhere.

export { PrismaClient, Prisma, type Order, type User } from '@prisma/client';
import type { PrismaClient } from '@prisma/client';

/** The one configured client the whole project shares. */
export declare const prisma: PrismaClient;

/** A second one, pointed at a replica, because a real wrapper exports several. */
export declare const readonlyPrisma: PrismaClient;
